import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Loader2, Check, Sparkles } from 'lucide-react';
import { useReportStore } from '../store/reportStore';

const PIPELINE_STEPS = [
  { label: 'Classifying your idea...', emoji: '🏷️' },
  { label: 'Researching market trends...', emoji: '📈' },
  { label: 'Scanning government schemes...', emoji: '🏛️' },
  { label: 'Evaluating competition...', emoji: '🔍' },
  { label: 'Calculating validation score...', emoji: '📊' },
  { label: 'Writing your full report...', emoji: '📝' },
];

export default function Generating() {
  const navigate = useNavigate();
  const { currentReportId, generationStatus, pipelineStep } = useReportStore();
  const [activeStep, setActiveStep] = useState(0);
  const [dots, setDots] = useState('');

  // Animate dots
  useEffect(() => {
    const interval = setInterval(() => {
      setDots(prev => prev.length >= 3 ? '' : prev + '.');
    }, 500);
    return () => clearInterval(interval);
  }, []);

  // Auto-advance steps for visual effect
  useEffect(() => {
    const stepFromServer = pipelineStep;
    if (stepFromServer > activeStep) {
      setActiveStep(stepFromServer);
    } else {
      // Simulate step progression if server is slow
      const timer = setTimeout(() => {
        setActiveStep(prev => Math.min(prev + 1, PIPELINE_STEPS.length - 1));
      }, 8000);
      return () => clearTimeout(timer);
    }
  }, [pipelineStep, activeStep]);

  // Navigate on completion
  useEffect(() => {
    if (generationStatus === 'complete' && currentReportId) {
      setTimeout(() => navigate(`/report/${currentReportId}`), 1000);
    }
    if (generationStatus === 'error') {
      setTimeout(() => navigate('/onboard'), 3000);
    }
  }, [generationStatus, currentReportId, navigate]);

  return (
    <div className="min-h-screen bg-background flex items-center justify-center px-4">
      {/* Ambient Glow */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] rounded-full bg-primary/10 blur-[200px] animate-pulse" />
      </div>

      <div className="relative z-10 max-w-md w-full">
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="text-center mb-10"
        >
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary/10 border border-primary/20 mb-4">
            <Sparkles className="w-8 h-8 text-primary animate-spin-slow" />
          </div>
          <h1 className="font-syne text-3xl font-bold mb-2">Analysing Your Idea</h1>
          <p className="text-muted-foreground">This usually takes 45-60 seconds{dots}</p>
        </motion.div>

        <div className="space-y-3">
          {PIPELINE_STEPS.map((step, i) => {
            const isActive = i === activeStep;
            const isDone = i < activeStep;

            return (
              <motion.div
                key={step.label}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: isDone || isActive ? 1 : 0.3, y: 0 }}
                transition={{ duration: 0.4, delay: i * 0.1 }}
                className={`flex items-center gap-4 p-4 rounded-xl transition-all duration-500 ${
                  isActive ? 'bg-card border border-primary/30 shadow-[0_0_20px_rgba(0,223,130,0.1)]' :
                  isDone ? 'bg-card/50 border border-border/50' : 'bg-transparent border border-transparent'
                }`}
              >
                <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 transition-all ${
                  isDone ? 'bg-primary text-primary-foreground' :
                  isActive ? 'bg-primary/20' : 'bg-card border border-border'
                }`}>
                  {isDone ? <Check className="w-4 h-4" /> :
                   isActive ? <Loader2 className="w-4 h-4 text-primary animate-spin" /> :
                   <span className="text-sm">{step.emoji}</span>}
                </div>

                <span className={`text-sm font-medium transition-colors ${
                  isActive ? 'text-foreground' :
                  isDone ? 'text-muted-foreground' : 'text-muted-foreground/50'
                }`}>
                  {step.label}
                </span>
              </motion.div>
            );
          })}
        </div>

        {/* Progress bar */}
        <div className="mt-8 h-1 bg-card rounded-full overflow-hidden">
          <motion.div
            className="h-full bg-gradient-to-r from-primary to-secondary rounded-full"
            initial={{ width: '0%' }}
            animate={{ width: `${Math.min(((activeStep + 1) / PIPELINE_STEPS.length) * 100, 100)}%` }}
            transition={{ duration: 0.5 }}
          />
        </div>

        {generationStatus === 'error' && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-center text-destructive mt-4 text-sm"
          >
            Something went wrong. Redirecting...
          </motion.p>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, ArrowRight, TrendingUp, Loader2 } from 'lucide-react';
import { useAuthStore } from '../store/authStore';
import { useReportStore } from '../store/reportStore';
import { INDUSTRIES, INVESTMENT_STAGES, BUDGETS } from '../types/report';

export default function InvestorForm() {
  const navigate = useNavigate();
  const { token } = useAuthStore();
  const { setReportId, setStatus } = useReportStore();
  const [step, setStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [form, setForm] = useState({
    preferredSectors: [] as string[],
    investmentStage: '',
    riskAppetite: '' as 'low' | 'medium' | 'high' | '',
    budgetRange: '',
    geography: '',
    interestKeywords: '',
  });

  const toggleSector = (sector: string) => {
    setForm(prev => ({
      ...prev,
      preferredSectors: prev.preferredSectors.includes(sector)
        ? prev.preferredSectors.filter(s => s !== sector)
        : prev.preferredSectors.length < 3
          ? [...prev.preferredSectors, sector]
          : prev.preferredSectors,
    }));
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    setStatus('generating');

    try {
      const body = {
        role: 'investor',
        preferredSectors: form.preferredSectors,
        investmentStage: form.investmentStage,
        riskAppetite: form.riskAppetite,
        budgetRange: form.budgetRange,
        geography: form.geography,
        interestKeywords: form.interestKeywords ? form.interestKeywords.split(',').map(k => k.trim()) : [],
      };

      const response = await fetch('/api/report/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify(body),
      });

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      if (!reader) throw new Error('No response body');

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        const text = decoder.decode(value);
        for (const line of text.split('\n')) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6));
              if (data.event === 'pipeline_start') { setReportId(data.reportId); navigate('/generating'); }
              else if (data.event === 'pipeline_complete') { setStatus('complete'); navigate(`/report/${data.reportId}`); return; }
              else if (data.event === 'pipeline_error') { setStatus('error'); alert(data.message); setIsSubmitting(false); return; }
            } catch {}
          }
        }
      }
    } catch { alert('Connection error'); setIsSubmitting(false); }
  };

  const selectClass = 'w-full px-4 py-3 rounded-xl bg-card border border-border text-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 appearance-none';

  return (
    <div className="min-h-screen bg-background pt-24 pb-16 px-4">
      <div className="max-w-2xl mx-auto">
        <div className="flex items-center justify-center gap-2 mb-10">
          {[1, 2].map(s => (
            <div key={s} className="flex items-center gap-2">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${s === step ? 'bg-blue-500 text-white scale-110' : s < step ? 'bg-blue-500/20 text-blue-400' : 'bg-card border border-border text-muted-foreground'}`}>{s}</div>
              {s < 2 && <div className={`w-12 h-0.5 ${s < step ? 'bg-blue-500' : 'bg-border'}`} />}
            </div>
          ))}
        </div>

        <AnimatePresence mode="wait">
          <motion.div key={step} initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} className="bg-card border border-border rounded-2xl p-8 shadow-xl">
            {step === 1 && (
              <div className="space-y-6">
                <div>
                  <h2 className="font-syne text-2xl font-bold flex items-center gap-2"><TrendingUp className="w-6 h-6 text-blue-400" /> Investment Profile</h2>
                  <p className="text-sm text-muted-foreground mt-1">Tell us about your investment focus.</p>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium">Preferred Sectors (up to 3)</label>
                  <div className="flex flex-wrap gap-2">
                    {INDUSTRIES.map(ind => (
                      <button key={ind}
                        onClick={() => toggleSector(ind)}
                        className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all ${form.preferredSectors.includes(ind) ? 'bg-blue-500 text-white' : 'bg-card border border-border text-muted-foreground hover:border-blue-500/50'}`}
                      >{ind}</button>
                    ))}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-sm font-medium">Investment Stage</label>
                    <select className={selectClass} value={form.investmentStage} onChange={e => setForm(p => ({ ...p, investmentStage: e.target.value }))}>
                      <option value="">Select...</option>
                      {INVESTMENT_STAGES.map(s => <option key={s}>{s}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-sm font-medium">Budget Range</label>
                    <select className={selectClass} value={form.budgetRange} onChange={e => setForm(p => ({ ...p, budgetRange: e.target.value }))}>
                      <option value="">Select...</option>
                      {BUDGETS.map(b => <option key={b}>{b}</option>)}
                    </select>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium">Risk Appetite</label>
                  <div className="flex gap-3">
                    {(['low', 'medium', 'high'] as const).map(r => (
                      <button key={r} onClick={() => setForm(p => ({ ...p, riskAppetite: r }))}
                        className={`flex-1 py-2.5 rounded-xl text-sm font-medium capitalize transition-all ${form.riskAppetite === r ? 'bg-blue-500 text-white' : 'bg-card border border-border text-muted-foreground hover:border-blue-500/50'}`}
                      >{r === 'low' ? '🛡️ Conservative' : r === 'medium' ? '⚖️ Moderate' : '🚀 Aggressive'}</button>
                    ))}
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-sm font-medium">Geography</label>
                  <input className="w-full px-4 py-3 rounded-xl bg-card border border-border text-foreground placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/50"
                    placeholder="e.g. India, Southeast Asia" value={form.geography} onChange={e => setForm(p => ({ ...p, geography: e.target.value }))} />
                </div>

                <div className="space-y-1">
                  <label className="text-sm font-medium">Interest Keywords <span className="text-muted-foreground">(optional, comma-separated)</span></label>
                  <input className="w-full px-4 py-3 rounded-xl bg-card border border-border text-foreground placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/50"
                    placeholder="e.g. AI, sustainability, B2B" value={form.interestKeywords} onChange={e => setForm(p => ({ ...p, interestKeywords: e.target.value }))} />
                </div>
              </div>
            )}

            {step === 2 && (
              <div className="space-y-6">
                <h2 className="font-syne text-2xl font-bold">Review & Submit</h2>
                <div className="space-y-3">
                  <div className="flex gap-4 py-2 border-b border-border/50"><span className="text-sm text-muted-foreground w-32">Sectors</span><span className="text-sm">{form.preferredSectors.join(', ') || '—'}</span></div>
                  <div className="flex gap-4 py-2 border-b border-border/50"><span className="text-sm text-muted-foreground w-32">Stage</span><span className="text-sm">{form.investmentStage || '—'}</span></div>
                  <div className="flex gap-4 py-2 border-b border-border/50"><span className="text-sm text-muted-foreground w-32">Risk</span><span className="text-sm capitalize">{form.riskAppetite || '—'}</span></div>
                  <div className="flex gap-4 py-2 border-b border-border/50"><span className="text-sm text-muted-foreground w-32">Budget</span><span className="text-sm">{form.budgetRange || '—'}</span></div>
                  <div className="flex gap-4 py-2"><span className="text-sm text-muted-foreground w-32">Geography</span><span className="text-sm">{form.geography || '—'}</span></div>
                </div>
              </div>
            )}
          </motion.div>
        </AnimatePresence>

        <div className="flex justify-between mt-6">
          <button onClick={() => step > 1 ? setStep(1) : navigate('/onboard')} className="flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm text-muted-foreground hover:text-foreground">
            <ArrowLeft className="w-4 h-4" /> Back
          </button>
          {step < 2 ? (
            <button onClick={() => setStep(2)} className="flex items-center gap-2 px-6 py-2.5 rounded-xl bg-blue-500 text-white font-medium hover:bg-blue-600">
              Next <ArrowRight className="w-4 h-4" />
            </button>
          ) : (
            <button onClick={handleSubmit} disabled={isSubmitting} className="flex items-center gap-2 px-6 py-2.5 rounded-xl bg-blue-500 text-white font-semibold hover:bg-blue-600 disabled:opacity-50">
              {isSubmitting ? <><Loader2 className="w-4 h-4 animate-spin" /> Analysing...</> : <><TrendingUp className="w-4 h-4" /> Discover Opportunities</>}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import {
  Target, Shield, Lightbulb, Users, BarChart3, Swords, TrendingUp,
  Landmark, Rocket, AlertTriangle, CheckCircle, Calendar, MessageSquare,
  Share2, Loader2, ChevronDown, ChevronUp, ExternalLink
} from 'lucide-react';
import {
  RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis,
  Radar, ResponsiveContainer
} from 'recharts';
import { useAuthStore } from '../store/authStore';

interface ReportData {
  id: string;
  role: string;
  status: string;
  inputData: any;
  outputData: any;
  score: number;
  verdict: string;
  shareToken: string | null;
  ideaName: string;
  createdAt: string;
}

const SEVERITY_COLORS = { low: 'text-emerald-400', medium: 'text-amber-400', high: 'text-red-400' };
const THREAT_BG = { low: 'bg-emerald-500/10 text-emerald-400', medium: 'bg-amber-500/10 text-amber-400', high: 'bg-red-500/10 text-red-400' };

function VerdictBanner({ verdict, score, rationale }: { verdict: string; score: number; rationale: string }) {
  const config: Record<string, { bg: string; border: string; shadow: string; label: string; emoji: string }> = {
    go: { bg: 'from-emerald-500/10 to-teal-500/5', border: 'border-emerald-500/30', shadow: 'shadow-emerald-500/10', label: 'GO', emoji: '🚀' },
    revise: { bg: 'from-amber-500/10 to-yellow-500/5', border: 'border-amber-500/30', shadow: 'shadow-amber-500/10', label: 'REVISE', emoji: '🔄' },
    'no-go': { bg: 'from-red-500/10 to-rose-500/5', border: 'border-red-500/30', shadow: 'shadow-red-500/10', label: 'NO-GO', emoji: '⛔' },
  };
  const c = config[verdict] || config['revise'];

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className={`relative p-8 rounded-2xl bg-gradient-to-br ${c.bg} border ${c.border} ${c.shadow} shadow-2xl overflow-hidden`}
    >
      <div className="flex flex-col md:flex-row items-center gap-6">
        {/* Score Ring */}
        <div className="relative w-32 h-32 shrink-0">
          <svg className="w-32 h-32 -rotate-90" viewBox="0 0 120 120">
            <circle cx="60" cy="60" r="50" fill="none" stroke="currentColor" strokeWidth="8" className="text-border/30" />
            <circle cx="60" cy="60" r="50" fill="none" stroke="url(#scoreGradient)" strokeWidth="8" strokeLinecap="round"
              strokeDasharray={`${(score / 100) * 314} 314`} />
            <defs>
              <linearGradient id="scoreGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor={verdict === 'go' ? '#00DF82' : verdict === 'revise' ? '#F6C144' : '#FF4A4A'} />
                <stop offset="100%" stopColor={verdict === 'go' ? '#00A3FF' : verdict === 'revise' ? '#FF9500' : '#FF0000'} />
              </linearGradient>
            </defs>
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="font-syne text-3xl font-bold">{score}</span>
            <span className="text-xs text-muted-foreground">/100</span>
          </div>
        </div>

        <div className="text-center md:text-left">
          <div className="text-sm font-mono text-muted-foreground mb-1">VERDICT</div>
          <div className="font-syne text-4xl font-bold flex items-center gap-3">
            <span>{c.emoji}</span>
            <span>{c.label}</span>
          </div>
          <p className="text-sm text-muted-foreground mt-2 max-w-lg">{rationale}</p>
        </div>
      </div>
    </motion.div>
  );
}

function SectionCard({ title, icon: Icon, children, defaultOpen = true }: { title: string; icon: any; children: React.ReactNode; defaultOpen?: boolean }) {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      className="bg-card border border-border rounded-2xl overflow-hidden"
    >
      <button onClick={() => setOpen(!open)} className="w-full flex items-center justify-between p-5 hover:bg-accent/30 transition-colors text-left">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center">
            <Icon className="w-5 h-5 text-primary" />
          </div>
          <h3 className="font-syne font-bold text-lg">{title}</h3>
        </div>
        {open ? <ChevronUp className="w-5 h-5 text-muted-foreground" /> : <ChevronDown className="w-5 h-5 text-muted-foreground" />}
      </button>
      {open && <div className="px-5 pb-5 pt-0 border-t border-border/50">{children}</div>}
    </motion.div>
  );
}

export default function ReportPage() {
  const { reportId } = useParams();
  const { token } = useAuthStore();
  const [report, setReport] = useState<ReportData | null>(null);
  const [loading, setLoading] = useState(true);
  const [shareLink, setShareLink] = useState('');

  useEffect(() => {
    const fetchReport = async () => {
      try {
        const res = await fetch(`/api/report/${reportId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.ok) {
          const data = await res.json();
          setReport(data);
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchReport();
  }, [reportId, token]);

  const handleShare = async () => {
    try {
      const res = await fetch(`/api/report/${reportId}/share`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      setShareLink(data.shareUrl);
      navigator.clipboard.writeText(data.shareUrl);
    } catch {}
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-primary animate-spin" />
      </div>
    );
  }

  if (!report || !report.outputData) {
    return (
      <div className="min-h-screen bg-background flex flex-col items-center justify-center gap-4">
        <p className="text-muted-foreground">Report not found or still generating.</p>
        <Link to="/history" className="text-primary hover:underline text-sm">← Back to history</Link>
      </div>
    );
  }

  const output = report.outputData;
  const isStartup = output.role === 'startup';
  const sections = output.sections;
  const scores = isStartup ? output.dimensionScores : null;

  // Prepare radar data
  const radarData = scores ? Object.entries(scores).map(([key, val]: [string, any]) => ({
    dimension: key.replace(/([A-Z])/g, ' $1').trim(),
    score: val.score || 0,
    fullMark: 10,
  })) : [];

  return (
    <div className="min-h-screen bg-background pt-24 pb-16 px-4">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <p className="text-xs font-mono text-muted-foreground mb-1">REPORT</p>
            <h1 className="font-syne text-3xl font-bold">{report.ideaName || 'Intelligence Report'}</h1>
            <p className="text-sm text-muted-foreground mt-1">
              Generated {new Date(report.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })}
            </p>
          </div>
          <div className="flex gap-2">
            <button onClick={handleShare} className="flex items-center gap-2 px-4 py-2 rounded-lg bg-card border border-border text-sm hover:bg-accent/30 transition-colors">
              <Share2 className="w-4 h-4" /> Share
            </button>
            <Link to={`/report/${reportId}/chat`} className="flex items-center gap-2 px-4 py-2 rounded-lg bg-primary text-primary-foreground text-sm font-medium hover:bg-primary/90 transition-colors">
              <MessageSquare className="w-4 h-4" /> Ask Questions
            </Link>
          </div>
        </div>

        {shareLink && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="bg-primary/10 border border-primary/20 rounded-lg p-3 flex items-center justify-between">
            <p className="text-sm text-primary truncate">{shareLink}</p>
            <span className="text-xs text-primary font-medium shrink-0 ml-2">Copied!</span>
          </motion.div>
        )}

        {/* Verdict Banner (Startup only) */}
        {isStartup && output.compositeScore !== undefined && (
          <VerdictBanner verdict={output.verdict} score={output.compositeScore} rationale={output.verdictRationale} />
        )}

        {/* Radar Chart (Startup only) */}
        {isStartup && radarData.length > 0 && (
          <SectionCard title="Dimension Scores" icon={BarChart3}>
            <div className="h-80 mt-4">
              <ResponsiveContainer>
                <RadarChart data={radarData}>
                  <PolarGrid stroke="#1e293b" />
                  <PolarAngleAxis dataKey="dimension" tick={{ fontSize: 10, fill: '#94a3b8' }} />
                  <PolarRadiusAxis angle={30} domain={[0, 10]} tick={{ fontSize: 10, fill: '#475569' }} />
                  <Radar name="Score" dataKey="score" stroke="#00DF82" fill="#00DF82" fillOpacity={0.15} strokeWidth={2} />
                </RadarChart>
              </ResponsiveContainer>
            </div>
            <div className="grid grid-cols-2 gap-3 mt-4">
              {scores && Object.entries(scores).map(([key, val]: [string, any]) => (
                <div key={key} className="flex items-start gap-3 p-3 rounded-lg bg-accent/30">
                  <div className={`text-sm font-bold ${val.score >= 7 ? 'text-emerald-400' : val.score >= 4 ? 'text-amber-400' : 'text-red-400'}`}>
                    {val.score}/10
                  </div>
                  <div>
                    <div className="text-xs font-medium capitalize">{key.replace(/([A-Z])/g, ' $1')}</div>
                    <div className="text-xs text-muted-foreground mt-0.5">{val.rationale}</div>
                  </div>
                </div>
              ))}
            </div>
          </SectionCard>
        )}

        {/* Startup-specific sections */}
        {isStartup && (
          <>
            {sections.ideaSummary && (
              <SectionCard title="Idea Summary" icon={Lightbulb}>
                <p className="text-sm leading-relaxed mt-3 whitespace-pre-line">{sections.ideaSummary}</p>
