// ── Report types ──

export interface DimensionScore {
  score: number;
  rationale: string;
}

export interface CompetitorCard {
  name: string;
  description: string;
  differentiator: string;
  threat: 'low' | 'medium' | 'high';
}

export interface TrendItem {
  title: string;
  summary: string;
  source?: string;
  date?: string;
}

export interface SchemeItem {
  name: string;
  description: string;
  eligibility: string;
  benefit: string;
  link?: string;
}

export interface RiskItem {
  risk: string;
  severity: 'low' | 'medium' | 'high';
  mitigation: string;
}

export interface RecommendationItem {
  priority: number;
  action: string;
  reason: string;
}

export interface ActionWeek {
  week: number;
  goal: string;
  tasks: string[];
}

export interface NewsArticle {
  title: string;
  description: string;
  source: string;
  publishedAt: string;
  url: string;
}

export interface StartupReport {
  id: string;
  role: 'startup';
  status: 'pending' | 'generating' | 'complete' | 'failed';
  inputData: any;
  outputData: {
    role: 'startup';
    generatedAt: string;
    dimensionScores: Record<string, DimensionScore>;
    compositeScore: number;
    verdict: 'go' | 'revise' | 'no-go';
    verdictRationale: string;
    sections: {
      ideaSummary: string;
      problemAnalysis: string;
      targetAudienceAnalysis: string;
      marketOpportunity: {
        tamEstimate: string;
        samEstimate: string;
        somEstimate: string;
        narrative: string;
      };
      competitionAnalysis: {
        competitors: CompetitorCard[];
        positioning: string;
        gaps: string[];
      };
      industryTrends: TrendItem[];
      governmentSchemes: SchemeItem[];
      mvpSuggestions: string;
      risks: RiskItem[];
      recommendations: RecommendationItem[];
      fundingFit: string;
      actionPlan: ActionWeek[];
      finalVerdict: string;
    };
    newsArticles: NewsArticle[];
    researchContext: string;
  };
  score: number;
  verdict: string;
  shareToken: string | null;
  ideaName: string;
  createdAt: string;
}

export interface InvestorReport {
  id: string;
  role: 'investor';
  status: string;
  inputData: any;
  outputData: {
    role: 'investor';
    generatedAt: string;
    sections: {
      sectorOverview: string;
      trendingCategories: Array<{
        name: string;
        growthSignal: 'high' | 'medium' | 'low';
        description: string;
        examples: string[];
      }>;
      redFlags: Array<{ flag: string; detail: string }>;
      policyImpact: string;
      opportunityMap: Array<{
        sector: string;
        maturity: number;
        growthRate: number;
        marketSize: string;
      }>;
      sectorsToWatch: string[];
      dueDiligenceAngles: string[];
    };
  };
  score: null;
  verdict: string;
  shareToken: string | null;
  ideaName: string | null;
  createdAt: string;
}

export interface StudentReport {
  id: string;
  role: 'student';
  status: string;
  inputData: any;
  outputData: {
    role: 'student';
    generatedAt: string;
    sections: {
      ideaMatches: Array<{
        rank: number;
        name: string;
        description: string;
        feasibility: string;
        budgetRequired: string;
        keyChallenge: string;
      }>;
      skillsToLearn: Array<{ skill: string; priority: number; resource: string }>;
      mvpRoadmap?: Array<{
        month: number;
        goal: string;
        tasks: Array<{ task: string; category: string }>;
      }>;
      freeResources: Array<{ name: string; url: string; description: string }>;
      studentPrograms: Array<{ name: string; description: string; eligibility: string }>;
      validationGuide: string;
    };
  };
  score: null;
  verdict: string;
  shareToken: string | null;
  ideaName: string | null;
  createdAt: string;
}

export type Report = StartupReport | InvestorReport | StudentReport;

export interface ReportHistoryItem {
  id: string;
  role: string;
  ideaName: string | null;
  score: number | null;
  verdict: string;
  status: string;
  createdAt: string;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
}
